/**
 * @title IMocV1
 * @author Money On Chain
 * @notice Interface for MoC V1 main contract
 */
interface IMocV1 {
    /// @notice Mint DOC sending rBTC as collateral
    /// @param btcToMint Amount of rBTC to swap for DOC
    /// @dev msg.value must be greater than or equal to btcToMint + fees. Surplus will be returned to the caller.
    function mintDoc(uint256 btcToMint) external payable;

    /// @notice Redeem rBTC by burning DOC
    /// @param docAmount Amount of DOC to swap for rBTC
    function redeemFreeDoc(uint256 docAmount) external;
}

/**
 * @title IMocStateV1
 * @author Money On Chain
 * @notice Interface for MoC V1 state contract
 */
interface IMocStateV1 {
    /// @notice Returns the current price of Bitcoin in rBTC with 18 decimals
    /// @return The Bitcoin price with 18 decimals
    function getBitcoinPrice() external view returns (uint256);

    /// @notice Returns the absolute maximum DOC that can be minted in the system
    /// @return The absolute maximum DOC amount
    function absoluteMaxDoc() external view returns (uint256);

    /// @notice Returns the amount of DOC that can currently be redeemed for rBTC
    /// @return The redeemable DOC amount
    function freeDoc() external view returns (uint256);

    /// @notice Gets the BTC price provider address
    /// @return The address of the BTC price provider
    function getBtcPriceProvider() external view returns (address);

    /// @notice Gets the total DOC supply
    /// @return The total DOC supply
    function docTotalSupply() external view returns (uint256);

    enum States {
        // State 0
        Liquidated,
        // State 1
        BProDiscount,
        // State 2
        BelowCobj,
        // State 3
        AboveCobj
    }

    /// @notice Gets the current state of the system
    /// @return The current state of the system
    function state() external view returns (States);
}

/**
 * @title IMocInrateV1
