pragma solidity 0.8.24;

import { MocLendingQueue } from "./MocLendingQueue.sol";
import { MocLendingPool as Pool } from "./lib/MocLendingPool.sol";
import { FixedPoint } from "./lib/FixedPoint.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Coin } from "./lib/Coin.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title MocLendingManager
 * @author Money On Chain
 * @notice Main contract for managing lending and borrowing operations in the MoC protocol
 */
contract MocLendingManager is MocLendingQueue {
    using Pool for Pool.State;
    using SafeERC20 for IERC20;
    using Coin for IERC20;
    using FixedPoint for uint256;

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when a function meant to be called only by this contract is called by another address
    error OnlySelf();

    /// @notice Thrown when the TP token is not valid in the MoC system
    error InvalidTPToken();

    /// @notice Thrown when trying to operate with a pool that has not been initialized
    error PoolNotInitialized();

    /// @notice Thrown when trying to open a new vault on a liquidated bucket
    error LiquidatedBucketNewVault();

    // -----------------
    // Events
    // -----------------

    /// @notice Emitted when a user deposits TP tokens into the lending pool
    /// @param user The address of the user depositing
    /// @param recipient The address receiving the deposit units
    /// @param tpToken The TP token address
    /// @param tpAmount The amount of TP tokens deposited
    /// @param depositUnits The amount of deposit units received
    event Deposit(
        address indexed user,
        address indexed recipient,
        address indexed tpToken,
        uint256 tpAmount,
        uint256 depositUnits
    );

    /// @notice Emitted when a user withdraws TP tokens from the lending pool
    /// @param user The address of the user withdrawing
    /// @param recipient The address receiving the TP tokens
    /// @param tpToken The TP token address
    /// @param depositUnits The amount of deposit units withdrawn
    /// @param tpAmount The amount of TP tokens received
    event Withdraw(
        address indexed user,
        address indexed recipient,
        address indexed tpToken,
        uint256 depositUnits,
        uint256 tpAmount
    );

    /// @notice Emitted when AC tokens are added to a vault as collateral
    /// @param user The address adding the collateral
    /// @param recipient The address whose vault receives the collateral
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acAmount The amount of AC tokens added
    event AddACtoVault(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acAmount
    );

    /// @notice Emitted when AC tokens are removed from a vault
    /// @param user The address whose vault is being modified
    /// @param recipient The address receiving the AC tokens
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acAmount The amount of AC tokens removed
    event RemoveACfromVault(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acAmount
    );

    /// @notice Emitted when a user borrows TP tokens
    /// @param user The address whose vault is used as collateral
    /// @param recipient The address receiving the TP tokens
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param tpAmount The amount of TP tokens borrowed
    /// @param creditUnits The amount of credit units issued
    event Borrow(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 tpAmount,
        uint256 creditUnits
    );

    /// @notice Emitted when a user repays borrowed TP tokens
    /// @param user The address repaying
    /// @param recipient The address whose debt is being repaid
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param creditUnits The amount of credit units repaid
    /// @param tpAmount The amount of TP tokens repaid
    /// @param tpToFeeFlow The amount of TP tokens sent to fee flow
    event Repay(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 creditUnits,
        uint256 tpAmount,
        uint256 tpToFeeFlow
    );

    /// @notice Emitted when a user repays borrowed TP tokens using AC from their vault
    /// @param user The address repaying
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param creditUnits The amount of credit units repaid
    /// @param acSold The amount of AC tokens sold
    /// @param tpAmount The amount of TP tokens repaid
    /// @param tpToFeeFlow The amount of TP tokens sent to fee flow
    event RepayWithAC(
        address indexed user,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 creditUnits,
        uint256 acSold,
        uint256 tpAmount,
        uint256 tpToFeeFlow
    );

    /// @notice Emitted when a vault is liquidated
    /// @param liquidator The address initiating the liquidation
    /// @param user The address being liquidated
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acSwapped The amount of AC swapped in this step
    /// @param tpPaid The actual TP amount paid
    /// @param acLiquidationPayment The AC payment sent to the liquidation engine
    /// @param tpToFeeFlow The amount of TP tokens sent to fee flow
    /// @param isComplete Whether the liquidation is now complete
    event Liquidate(
        address liquidator,
        address indexed user,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acSwapped,
        uint256 tpPaid,
        uint256 acLiquidationPayment,
        uint256 tpToFeeFlow,
        bool isComplete
    );

    /// @notice Emitted with the absolute state of a vault after any successful mutation
    /// @param user The vault owner
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acBalance The vault's resulting AC collateral balance, excluding the reserved liquidation payment
    /// @param creditUnits The vault's resulting credit unit balance
    /// @param liquidating Whether the vault is in a multi-step liquidation
    event VaultStateUpdated(
        address indexed user,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acBalance,
        uint256 creditUnits,
        bool liquidating
    );

    /// @notice Emitted when TP tokens are injected into the lending pool
    /// @param tpToken The TP token address
    /// @param tpAmount The amount of TP tokens injected
    event TPInjection(address indexed tpToken, uint256 tpAmount);

    // -----------------
    // Modifiers
    // -----------------

    /// @notice Modifier to validate that a pool exists before executing a function
    /// @param tpToken_ The TP token address to check
    modifier poolExists(address tpToken_) {
        _poolExists(tpToken_);
        _;
    }

    /// @notice Internal function to validate that a pool exists
    /// @param tpToken_ The TP token address to check
    function _poolExists(address tpToken_) internal view {
        if (address(_pools[tpToken_].tpToken) == address(0)) revert PoolNotInitialized();
    }

    // -----------------
    // Storage
    // -----------------

    /// @notice Mapping from TP token address to its lending pool state
    mapping(address tpToken => Pool.State) internal _pools;
    /// @notice List of all TP tokens with initialized pools
    address[] public poolsList;
    /// @notice Maximum slippage allowed for swaps (1e18 = 100%, 0.01e18 = 1%)
    uint256 public maxSlippage;
    /// @notice Mapping of Moc Bucket and TP token to MoC fee flow address
    mapping(address mocBucket => mapping(address tpToken => address)) public mocFeeFlow;
    /// @notice Mapping of Moc Bucket and TP token to MoC Swapper Core contract
    mapping(address mocBucket => mapping(address tpToken => address)) public mocSwapperCore;
    /// @notice Mapping of Moc Bucket and TP token to MoC Swapper Exchange contract
    mapping(address mocBucket => mapping(address tpToken => address)) public mocSwapperExchange;
    /// @notice Recipient of completed-liquidation AC payments for each market
    mapping(address mocBucket => mapping(address tpToken => address)) public liquidationEngine;
    /// @notice AC payment reserved by newly indebted vaults, configured per market
    mapping(address mocBucket => mapping(address tpToken => uint256)) public liquidationPaymentAC;

    /// @notice Constructor to disable initializers for the implementation contract
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract
    /// @param governor_ The address of the governor contract
    /// @param pauser_ The address of the pauser contract
    /// @param mocAdapter_ The address of the MoC adapter contract
    /// @param maxSlippage_ The maximum slippage allowed for swaps (1e18 = 100%, 0.03e18 = 3%)
    /// @param initializeQueueParams_ The parameters for initializing the queue
    function initialize(
        address governor_,
        address pauser_,
        address mocAdapter_,
        uint256 maxSlippage_,
        InitializeQueueParams calldata initializeQueueParams_
    ) external initializer {
        maxSlippage = maxSlippage_;
        __MocLendingQueue_init({
            governor_: governor_,
            pauser_: pauser_,
            mocAdapter_: mocAdapter_,
            initializeQueueParams_: initializeQueueParams_
        });
    }

    /// @notice Create and initialize a new lending pool for a given TP token
    /// @param tpToken_ The TP token used in the lending pool.
    /// @param tpInjector_ TP Injector contract to inject TP tokens to the pool.
    /// @param minCoverage_ Minimum coverage ratio required for a vault. [PREC]
    /// @param liquidationCoverage_ Coverage threshold to liquidate a vault. [PREC]
    /// @param borrowFee_ Borrow fee taken from the interest paid by borrowers. [PREC]
    /// @param uKinkPoint_ Utilization rate at which the kink occurs. [PREC]
    /// @param uSoftSlope_ Slope of the interest rate model when utilization is below the kink point. [PREC]
    /// @param uMaxSlope_ Slope of the interest rate model when utilization is above the kink point. [PREC]
    /// @param injectionTimeSpan_ Time span to inject TP tokens.
    /// @param injectionBaseFactor_ Injection base factor used for calculating TP injection. [PREC]
    /// @param brakeFirstKink_ TP emission rate at which the first brake occurs. [PREC]
    /// @param brakeSecondKink_ TP emission rate at which the second brake occurs. [PREC]
    function initializePool(
        address tpToken_,
        address tpInjector_,
        uint256 minCoverage_,
        uint256 liquidationCoverage_,
        uint256 borrowFee_,
        uint256 uKinkPoint_,
        uint256 uSoftSlope_,
        uint256 uMaxSlope_,
        uint256 injectionTimeSpan_,
        uint256 injectionBaseFactor_,
        uint256 brakeFirstKink_,
        uint256 brakeSecondKink_
    ) external onlyAuthorizedChanger {
        if (!mocAdapter.isValidTP(tpToken_)) revert InvalidTPToken();
        Pool.State storage pool = _pools[tpToken_];
        pool.initialize(
            tpToken_,
            tpInjector_,
            minCoverage_,
            liquidationCoverage_,
            borrowFee_,
            uKinkPoint_,
            uSoftSlope_,
            uMaxSlope_,
            injectionTimeSpan_,
            injectionBaseFactor_,
            brakeFirstKink_,
            brakeSecondKink_
        );
        poolsList.push(tpToken_);
    }

    /// @notice Sets the maximum slippage allowed for swaps
    /// @param maxSlippage_ The new maximum slippage (1e18 = 100%, 0.01e18 = 1%)
    function setMaxSlippage(uint256 maxSlippage_) external onlyAuthorizedChanger {
        maxSlippage = maxSlippage_;
    }

    /// @notice Sets the MoC fee flow address for a given Moc Bucket and TP token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param feeFlow_ The new fee flow address
    function setMocFeeFlow(address mocBucket_, address tpToken_, address feeFlow_) external onlyAuthorizedChanger {
        mocFeeFlow[mocBucket_][tpToken_] = feeFlow_;
    }

    /// @notice Sets the MoC Swapper Core contract for a given Moc Bucket and TP token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param swapperCore_ The new Swapper Core address
    function setMocSwapperCore(
        address mocBucket_,
        address tpToken_,
        address swapperCore_
    ) external onlyAuthorizedChanger {
        mocSwapperCore[mocBucket_][tpToken_] = swapperCore_;
    }

    /// @notice Sets the MoC Swapper Exchange contract for a given Moc Bucket and TP token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param swapperExchange_ The new Swapper Exchange address
    function setMocSwapperExchange(
        address mocBucket_,
        address tpToken_,
        address swapperExchange_
    ) external onlyAuthorizedChanger {
        mocSwapperExchange[mocBucket_][tpToken_] = swapperExchange_;
    }

    /// @notice Set the recipient of completed-liquidation AC payments for a market
    /// @param mocBucket_ The MoC bucket whose AC funds the payment
    /// @param tpToken_ The TP token identifying the lending market
    /// @param liquidationEngine_ The liquidation engine that receives reserved AC
    function setLiquidationEngine(
        address mocBucket_,
        address tpToken_,
        address liquidationEngine_
    ) external onlyAuthorizedChanger {
        liquidationEngine[mocBucket_][tpToken_] = liquidationEngine_;
    }

    /// @notice Set the AC payment that new debt positions must reserve
    /// @param mocBucket_ The MoC bucket whose AC funds the payment
    /// @param tpToken_ The TP token identifying the lending market
    /// @param amount_ The fixed AC amount to reserve for newly indebted vaults
    function setLiquidationPaymentAC(
        address mocBucket_,
        address tpToken_,
        uint256 amount_
    ) external onlyAuthorizedChanger {
        liquidationPaymentAC[mocBucket_][tpToken_] = amount_;
    }

    // -----------------
    // Pool Parameter Setters
    // -----------------

    /// @notice Set minimum coverage for a pool
    /// @param tpToken_ The TP token address
    /// @param minCoverage_ The new minimum coverage value [PREC]
    function setPoolMinCoverage(address tpToken_, uint256 minCoverage_) external onlyAuthorizedChanger {
        _pools[tpToken_].minCoverage = minCoverage_;
    }

    /// @notice Set liquidation coverage for a pool
    /// @param tpToken_ The TP token address
    /// @param liquidationCoverage_ The new liquidation coverage value [PREC]
    function setPoolLiquidationCoverage(address tpToken_, uint256 liquidationCoverage_) external onlyAuthorizedChanger {
        _pools[tpToken_].liquidationCoverage = liquidationCoverage_;
    }

    /// @notice Set borrow fee for a pool
    /// @param tpToken_ The TP token address
    /// @param borrowFee_ The new borrow fee value [PREC]
    function setPoolBorrowFee(address tpToken_, uint256 borrowFee_) external onlyAuthorizedChanger {
        Pool.State storage pool = _pools[tpToken_];
        // Accrue interest with old fee before applying the new one
        pool.accrueInterest();
        pool.borrowFee = borrowFee_;
    }

    /// @notice Set U kink point for a pool
    /// @param tpToken_ The TP token address
    /// @param uKinkPoint_ The new U kink point value [PREC]
    function setPoolUKinkPoint(address tpToken_, uint256 uKinkPoint_) external onlyAuthorizedChanger {
        Pool.State storage pool = _pools[tpToken_];
        // Accrue interest with old kink point before applying the new one
        pool.accrueInterest();
        pool.uKinkPoint = uKinkPoint_;
    }

    /// @notice Set U soft slope for a pool
    /// @param tpToken_ The TP token address
    /// @param uSoftSlope_ The new U soft slope value [PREC]
    function setPoolUSoftSlope(address tpToken_, uint256 uSoftSlope_) external onlyAuthorizedChanger {
        Pool.State storage pool = _pools[tpToken_];

        // Accrue interest with old soft slope before applying the new one
        pool.accrueInterest();
        pool.uSoftSlope = uSoftSlope_;
    }

    /// @notice Set U max slope for a pool
    /// @param tpToken_ The TP token address
    /// @param uMaxSlope_ The new U max slope value [PREC]
    function setPoolUMaxSlope(address tpToken_, uint256 uMaxSlope_) external onlyAuthorizedChanger {
        Pool.State storage pool = _pools[tpToken_];
        // Accrue interest with old max slope before applying the new one
        pool.accrueInterest();
        pool.uMaxSlope = uMaxSlope_;
    }

    /// @notice Set injection time span for a pool
    /// @param tpToken_ The TP token address
    /// @param injectionTimeSpan_ The new injection time span value (in seconds)
    function setPoolInjectionTimeSpan(address tpToken_, uint256 injectionTimeSpan_) external onlyAuthorizedChanger {
        _pools[tpToken_].injectionTimeSpan = injectionTimeSpan_;
    }

    /// @notice Set injection base factor for a pool
    /// @param tpToken_ The TP token address
    /// @param injectionBaseFactor_ The new injection base factor value [PREC]
    function setPoolInjectionBaseFactor(address tpToken_, uint256 injectionBaseFactor_) external onlyAuthorizedChanger {
        _pools[tpToken_].injectionBaseFactor = injectionBaseFactor_;
    }

    /// @notice Set brake first kink for a pool
    /// @param tpToken_ The TP token address
    /// @param brakeFirstKink_ The new brake first kink value [PREC]
    function setPoolBrakeFirstKink(address tpToken_, uint256 brakeFirstKink_) external onlyAuthorizedChanger {
        _pools[tpToken_].brakeFirstKink = brakeFirstKink_;
    }

    /// @notice Set brake second kink for a pool
    /// @param tpToken_ The TP token address
    /// @param brakeSecondKink_ The new brake second kink value [PREC]
    function setPoolBrakeSecondKink(address tpToken_, uint256 brakeSecondKink_) external onlyAuthorizedChanger {
        _pools[tpToken_].brakeSecondKink = brakeSecondKink_;
    }

    /// @notice Internal function to get and validate AC/TP price and AC token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @return pACtp The validated AC/TP price [PREC]
    /// @return acToken The validated AC token address
    function _validateAndGetPACtp(address mocBucket_, address tpToken_) internal view returns (uint256, address) {
        // reverts if mocBucket or price are invalid
        return mocAdapter.validateAndGetPACtp(mocBucket_, tpToken_);
    }

    /// @notice Internal helper: validates a bucket/TP pair and returns price, AC token, and liquidation status
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @return pACtp The current price of the TP token in AC
    /// @return acToken The address of the AC token
    /// @return isLiquidated True if the bucket has been liquidated
    function _validateAndGetPACtpAndLiquidated(
        address mocBucket_,
        address tpToken_
    ) internal view returns (uint256 pACtp, address acToken, bool isLiquidated) {
        return mocAdapter.validateAndGetPACtpAndLiquidated(mocBucket_, tpToken_);
    }

    /// @notice Internal function to transfer fees to the fee flow address
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param tpToFeeFlow The amount of TP tokens to transfer to the fee flow
    function _transferFees(address mocBucket_, address tpToken_, uint256 tpToFeeFlow) internal {
        address feeFlow = mocFeeFlow[mocBucket_][tpToken_];
        if (feeFlow != address(0) && tpToFeeFlow > 0) {
            IERC20(tpToken_).safeTransfer(feeFlow, tpToFeeFlow);
        }
    }

    /// @notice Transfer reserved AC to the liquidation engine configured for a market
    /// @param mocBucket_ The MoC bucket whose AC funds the payment
    /// @param tpToken_ The TP token identifying the lending market
    /// @param acToken_ The AC token to transfer, or address(0) for coinbase
    /// @param acLiquidationPayment_ The reserved AC amount to transfer
    function _transferLiquidationPayment(
        address mocBucket_,
        address tpToken_,
        address acToken_,
        uint256 acLiquidationPayment_
    ) internal {
        address engine = liquidationEngine[mocBucket_][tpToken_];
        if (engine != address(0) && acLiquidationPayment_ > 0) {
            IERC20(acToken_).coinTransfer(engine, acLiquidationPayment_);
        }
    }

    /// @notice Emit the current absolute state of a vault for off-chain projection
    /// @param pool_ The lending pool containing the vault
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    function _emitVaultStateUpdated(
        Pool.State storage pool_,
        address user_,
        address tpToken_,
        address mocBucket_
    ) internal {
        emit VaultStateUpdated(
            user_,
            tpToken_,
            mocBucket_,
            pool_.vaultACBalance[user_][mocBucket_],
            pool_.vaultCreditBalance[user_][mocBucket_],
            pool_.isLiquidating[user_][mocBucket_]
        );
    }

    /// @notice Deposit TP tokens into the lending pool.
    /// @param recipient_ the address that will receive the deposit units
    /// @param tpToken_ the address of the TP token to deposit
    /// @param tpAmount_ the amount of TP tokens to deposit
    function deposit(address recipient_, address tpToken_, uint256 tpAmount_) external notPaused poolExists(tpToken_) {
        Pool.State storage pool = _pools[tpToken_];
        uint256 depositUnits = pool.deposit(recipient_, tpAmount_);

        // transfer TP tokens from the depositor to this pool manager
        IERC20(tpToken_).safeTransferFrom(msg.sender, address(this), tpAmount_);

        emit Deposit(msg.sender, recipient_, tpToken_, tpAmount_, depositUnits);
    }

    /// @notice Withdraw TP tokens from the lending pool.
    /// @param recipient_ the address that will receive the TP tokens
    /// @param tpToken_ the address of the TP token to withdraw
    /// @param depositUnits_ the amount of deposit units to withdraw
    function withdraw(
        address recipient_,
        address tpToken_,
        uint256 depositUnits_
    ) external notPaused poolExists(tpToken_) {
        Pool.State storage pool = _pools[tpToken_];
        uint256 tpToWithdraw = pool.withdraw(msg.sender, depositUnits_);
        // transfer TP tokens from this pool manager to the recipient
        IERC20(tpToken_).safeTransfer(recipient_, tpToWithdraw);

        emit Withdraw(msg.sender, recipient_, tpToken_, depositUnits_, tpToWithdraw);
    }

    /// @notice Add AC tokens to the recipient's vault as collateral.
    /// @dev For ERC20, the sender must approve this contract to transfer the AC tokens before calling this function.
    /// For coinbase (address(0)), the sender must send the exact amount of coinbase as msg.value.
    /// @param recipient_ The address whose vault will receive the AC tokens
    /// @param tpToken_ The TP token associated with the lending pool.
    /// @param mocBucket_ The Moc Bucket which use the AC token to be added as collateral.
    /// @param acAmount_ The amount of AC tokens to add to the vault. (should match msg.value if acToken_ is coinbase)
    function addACtoVault(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 acAmount_
    ) external payable notPaused poolExists(tpToken_) {
        // bucket token must be part of the MoC system, reverts if invalid.
        // isLiquidated is true when the bucket has been liquidated
        (address acToken, bool isLiquidated) = mocAdapter.validateAndGetACToken(mocBucket_);

        IERC20(acToken).coinVerifyValue(acAmount_);

        Pool.State storage pool = _pools[tpToken_];

        // If the bucket is liquidated, only allow operations on existing vaults
        // (with AC balance or outstanding debt) to let users pay down debt or add collateral.
        // Prevent opening brand-new vaults on liquidated buckets.
        if (
            isLiquidated &&
            pool.vaultACBalance[recipient_][mocBucket_] + pool.liquidationPaymentReserved[recipient_][mocBucket_] ==
                0 &&
            pool.vaultCreditBalance[recipient_][mocBucket_] == 0
        ) revert LiquidatedBucketNewVault();

        pool.addACtoVault(recipient_, mocBucket_, acAmount_);

        // transfer AC tokens from the sender to this pool manager
        IERC20(acToken).coinTransferFrom(msg.sender, address(this), acAmount_);

        emit AddACtoVault(msg.sender, recipient_, tpToken_, mocBucket_, acAmount_);
        _emitVaultStateUpdated(pool, recipient_, tpToken_, mocBucket_);
    }

    /// @notice Remove AC tokens from the recipient's vault.
    /// @dev The recipient must maintain the minimum coverage ratio after removing the AC tokens.
    /// @param recipient_ The address whose vault will have AC tokens removed
    /// @param tpToken_ The TP token associated with the lending pool.
    /// @param mocBucket_ The Moc Bucket which uses the AC token to remove from the vault.
    /// @param acAmount_ The amount of AC tokens to remove from the vault.
    /// @return operId The operation ID if queued, 0 if executed immediately
    function removeACfromVault(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 acAmount_
    ) external payable notPaused nonReentrant poolExists(tpToken_) returns (uint256 operId) {
        if (useQueue) {
            return _queueOperation(OperType.REMOVE_AC_FROM_VAULT, recipient_, tpToken_, mocBucket_, acAmount_);
        } else {
            _executeRemoveACfromVault(msg.sender, recipient_, tpToken_, mocBucket_, acAmount_);
            return 0;
        }
    }

    /// @notice Internal function to execute removeACfromVault
    /// @param user_ The address whose vault will have AC tokens removed
    /// @param recipient_ The address who will receive the AC tokens
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param acAmount_ The amount of AC tokens to remove
    function _executeRemoveACfromVault(
        address user_,
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 acAmount_
    ) internal {
        // reverts if AC token is invalid or price is invalid
        (uint256 pACtp, address acToken) = _validateAndGetPACtp(mocBucket_, tpToken_);
        Pool.State storage pool = _pools[tpToken_];

        pool.removeACfromVault(user_, mocBucket_, acAmount_, pACtp, pool.minCoverage);
        // transfer AC tokens from this pool manager to the recipient
        IERC20(acToken).coinTransfer(recipient_, acAmount_);

        emit RemoveACfromVault(user_, recipient_, tpToken_, mocBucket_, acAmount_);
        _emitVaultStateUpdated(pool, user_, tpToken_, mocBucket_);
    }

    /// @notice Borrow TP tokens from the lending pool using AC tokens as collateral.
    /// @dev The recipient must have the AC tokens in their vault and maintain the
    /// minimum coverage ratio after borrowing.
    /// @param recipient_ The address whose vault will be used and who will receive the TP tokens
    /// @param tpToken_ The TP token to borrow.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    /// @param tpAmount_ The amount of TP tokens to borrow.
    /// @return operId The operation ID if queued, 0 if executed immediately
    function borrow(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 tpAmount_
    ) external payable notPaused poolExists(tpToken_) returns (uint256 operId) {
        if (useQueue) {
            return _queueOperation(OperType.BORROW, recipient_, tpToken_, mocBucket_, tpAmount_);
        } else {
            _executeBorrow(msg.sender, recipient_, tpToken_, mocBucket_, tpAmount_);
            return 0;
        }
    }

    /// @notice Internal function to execute borrow
    /// @param user_ The address whose vault will be used as collateral
    /// @param recipient_ The address who will receive the TP tokens
    /// @param tpToken_ The TP token to borrow
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpAmount_ The amount of TP tokens to borrow
    function _executeBorrow(
        address user_,
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 tpAmount_
    ) internal {
        // Fetch price and liquidation status in one adapter call.
        // Reject new borrows against a liquidated bucket
        // Once a bucket is liquidated, existing vaults are limited to deleveraging (repay /
        // removeAC). Creating new debt against a liquidated bucket is not allowed.
        (uint256 pACtp, , bool isLiquidated) = _validateAndGetPACtpAndLiquidated(mocBucket_, tpToken_);
        if (isLiquidated) revert LiquidatedBucketNewVault();

        Pool.State storage pool = _pools[tpToken_];

        uint256 liquidationPayment = liquidationPaymentAC[mocBucket_][tpToken_];
        uint256 creditUnits = pool.borrow(user_, mocBucket_, tpAmount_, pACtp, liquidationPayment);

        // transfer TP tokens from this pool manager to the recipient
        IERC20(tpToken_).safeTransfer(recipient_, tpAmount_);

        emit Borrow(user_, recipient_, tpToken_, mocBucket_, tpAmount_, creditUnits);
        _emitVaultStateUpdated(pool, user_, tpToken_, mocBucket_);
    }

    /// @notice Repay borrowed TP tokens to the lending pool.
    /// @dev The sender must approve this contract to transfer the TP tokens before calling this function.
    /// @param recipient_ The address whose debt will be repaid
    /// @param tpToken_ The TP token to repay.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    /// @param creditUnits_ The amount of credit units to repay.
    function repay(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 creditUnits_
    ) external notPaused poolExists(tpToken_) {
        Pool.State storage pool = _pools[tpToken_];
        (uint256 totalTPtoRepay, uint256 tpToFeeFlow) = pool.repay(recipient_, mocBucket_, creditUnits_);
        pool.releaseLiquidationPayment(recipient_, mocBucket_);

        // transfer TP tokens from the payer to this pool manager
        IERC20(tpToken_).safeTransferFrom(msg.sender, address(this), totalTPtoRepay);

        // transfer TP tokens from this pool manager to the MocFeeFlow
        _transferFees(mocBucket_, tpToken_, tpToFeeFlow);

        emit Repay(msg.sender, recipient_, tpToken_, mocBucket_, creditUnits_, totalTPtoRepay, tpToFeeFlow);
        _emitVaultStateUpdated(pool, recipient_, tpToken_, mocBucket_);
    }

    /// @notice Repay borrowed TP tokens to the lending pool using AC tokens from the sender's vault.
    /// @dev The sender must have enough AC tokens in their vault to cover the repayment and fees.
    /// Only the msg.sender can repay their own debt using their own AC tokens.
    /// @param tpToken_ The TP token to repay.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    /// @param creditUnits_ The amount of credit units to repay.
    /// @return operId The operation ID if queued, 0 if executed immediately
    function repayWithAC(
        address tpToken_,
        address mocBucket_,
        uint256 creditUnits_
    ) external payable notPaused poolExists(tpToken_) returns (uint256 operId) {
        if (useQueue) {
            return _queueOperation(OperType.REPAY_WITH_AC, msg.sender, tpToken_, mocBucket_, creditUnits_);
        } else {
            _executeRepayWithAC(msg.sender, tpToken_, mocBucket_, creditUnits_);
            return 0;
        }
    }

    /// @notice Internal function to execute repayWithAC
    /// @param user_ The address of the user repaying
    /// @param tpToken_ The TP token to repay
    /// @param mocBucket_ The Moc Bucket address
    /// @param creditUnits_ The amount of credit units to repay
    function _executeRepayWithAC(address user_, address tpToken_, address mocBucket_, uint256 creditUnits_) internal {
        // reverts if AC token is invalid or price is invalid
        (uint256 pACtp, address acToken) = _validateAndGetPACtp(mocBucket_, tpToken_);

        Pool.State storage pool = _pools[tpToken_];

        // Calculate TP needed for the repay (this also accrues interest)
        uint256 tpNeeded = pool.calculateTPforRepay(user_, mocBucket_, creditUnits_);

        // Swap AC for TP using both swappers if needed (Core first, then Exchange)
        (uint256 acSold, uint256 tpBought) = IERC20(acToken).swapTwoStepsExactOutput(
            mocSwapperCore[mocBucket_][tpToken_],
            mocSwapperExchange[mocBucket_][tpToken_],
            tpToken_,
            address(this),
            tpNeeded,
            pACtp.mulPrec(ONE - maxSlippage),
            true // revert if swaps fail
        );

        uint256 actualCreditUnitsToRepay = creditUnits_;
        // Calculate how many credit units this TP amount represents, if we bought less than needed
        if (tpBought < tpNeeded) {
            // [N] = [N] * [PREC] / [PREC]
            actualCreditUnitsToRepay = tpBought.divPrec(pool.lastPCU);
        }

        // Now do the actual repay with the TPs we obtained
        (uint256 totalTPtoRepay, uint256 tpToFeeFlow) = pool.repay(user_, mocBucket_, actualCreditUnitsToRepay);

        // Use liquidationCoverage instead of minCoverage since user is reducing debt
        pool.removeACfromVault(user_, mocBucket_, acSold, pACtp, pool.liquidationCoverage);
        // Unlock the payment only after the AC used by this repayment has been debited.
        pool.releaseLiquidationPayment(user_, mocBucket_);
        // transfer TP tokens from this pool manager to the MocFeeFlow
        _transferFees(mocBucket_, tpToken_, tpToFeeFlow);
        // transfer the surplus TP tokens (if any) back to the user
        if (tpBought > totalTPtoRepay) {
            IERC20(tpToken_).safeTransfer(user_, tpBought - totalTPtoRepay);
        }
        emit RepayWithAC(user_, tpToken_, mocBucket_, actualCreditUnitsToRepay, acSold, totalTPtoRepay, tpToFeeFlow);
        _emitVaultStateUpdated(pool, user_, tpToken_, mocBucket_);
    }

    /// @notice Trigger TP injection for a lending pool
    /// @dev This function can be called by anyone to inject TP tokens into the pool if enough time has passed
    /// since the last injection. The injection increases pool liquidity and affects interest rates.
    /// @param tpToken_ The TP token associated with the lending pool
    function triggerTPInjection(address tpToken_) external notPaused poolExists(tpToken_) {
        uint256 tpInjected = _pools[tpToken_].tpInjection();
        emit TPInjection(tpToken_, tpInjected);
    }

    /// @notice Liquidate an under-collateralized position.
    /// @dev This function can be called by anyone (including repeatedly) to liquidate a user's position.
    /// The liquidation uses AC tokens from the user's vault to swap for TP tokens to repay debt.
    /// Due to swap limits (maxACtoSwap), liquidation may require multiple transactions.
    /// The function tracks progress automatically and handles:
    /// - Partial swaps when maxACtoSwap limits are hit
    /// - Reserve pool usage when AC is insufficient to cover debt
    /// - Surplus TP returned to reserve pool
    /// @param user_ The address of the user to liquidate.
    /// @param tpToken_ The TP token associated with the lending pool.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    function liquidate(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external notPaused nonReentrant poolExists(tpToken_) {
        (uint256 pACtp, address acToken) = _validateAndGetPACtp(mocBucket_, tpToken_);
        Pool.State storage pool = _pools[tpToken_];

        // Check if liquidation is needed and get AC in vault
        uint256 acInVault = pool.triggerLiquidation(user_, mocBucket_, pACtp);

        // Swap AC for TP using both swappers if needed (Core first, then Exchange)
        (uint256 acSwapped, uint256 tpObtained) = IERC20(acToken).swapTwoSteps(
            mocSwapperCore[mocBucket_][tpToken_],
            mocSwapperExchange[mocBucket_][tpToken_],
            tpToken_,
            address(this),
            acInVault,
            pACtp.mulPrec(ONE - maxSlippage),
            true // revert if swaps fail
        );

        // Process liquidation step
        (uint256 tpToFeeFlow, bool isComplete, uint256 acLiquidationPayment) = pool.liquidate(
            user_,
            mocBucket_,
            acSwapped,
            tpObtained
        );

        // Transfer TP fees to MocFeeFlow if any
        _transferFees(mocBucket_, tpToken_, tpToFeeFlow);

        // The reserved AC is paid once, only when the whole vault liquidation completes.
        _transferLiquidationPayment(mocBucket_, tpToken_, acToken, acLiquidationPayment);

        // Emit liquidation event
        emit Liquidate(
            msg.sender,
            user_,
            tpToken_,
            mocBucket_,
            acSwapped,
            tpObtained,
            acLiquidationPayment,
            tpToFeeFlow,
            isComplete
        );
        _emitVaultStateUpdated(pool, user_, tpToken_, mocBucket_);
    }

    // ============ View Functions ============

    /// @notice Get the total number of initialized pools
    /// @return The number of pools
    function getPoolsCount() external view returns (uint256) {
        return poolsList.length;
    }

    /// @notice Get pool liquidity
    /// @param tpToken_ The TP token address
    /// @return The pool liquidity
    function getPoolLiquidity(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].liquidityFresh();
    }

    /// @notice Get pool credit supply
    /// @param tpToken_ The TP token address
    /// @return The pool credit supply
    function getPoolCreditSupply(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].creditSupply;
    }

    /// @notice Get pool deposit supply
    /// @param tpToken_ The TP token address
    /// @return The pool deposit supply
    function getPoolDepositSupply(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].depositSupply;
    }

    /// @notice Get user deposit balance
    /// @param user_ The user address
    /// @param tpToken_ The TP token address
    /// @return The user deposit balance
    function getUserDepositBalance(address user_, address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].depositBalance[user_];
    }

    /// @notice Get user vault credit balance
    /// @param user_ The user address
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return The user vault credit balance
    function getUserVaultCreditBalance(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256) {
        return _pools[tpToken_].vaultCreditBalance[user_][mocBucket_];
    }

    /// @notice Get user vault AC balance
    /// @param user_ The user address
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return The total user vault AC balance, including the reserved liquidation payment
    function getUserVaultACBalance(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256) {
        Pool.State storage pool = _pools[tpToken_];
        return pool.vaultACBalance[user_][mocBucket_] + pool.liquidationPaymentReserved[user_][mocBucket_];
    }

    /// @notice Get AC currently reserved for the vault's final liquidation payment
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token identifying the lending market
    /// @param mocBucket_ The MoC bucket identifying the vault
    /// @return The reserved AC liquidation payment
    function getUserVaultLiquidationPayment(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256) {
        return _pools[tpToken_].liquidationPaymentReserved[user_][mocBucket_];
    }

    /// @notice Get AC that participates in collateral coverage
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token identifying the lending market
    /// @param mocBucket_ The MoC bucket identifying the vault
    /// @return The AC balance included in coverage calculations
    function getUserVaultCollateralBalance(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256) {
        return _pools[tpToken_].vaultACBalance[user_][mocBucket_];
    }

    /// @notice Get price of credit unit
    /// @param tpToken_ The TP token address
    /// @return The price of credit unit
    function getPriceCreditUnit(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].priceCreditUnit();
    }

    /// @notice Get price of deposit unit
    /// @param tpToken_ The TP token address
    /// @return The price of deposit unit
    function getPriceDepositUnit(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].priceDepositUnit();
    }

    /// @notice Get pool reserve
    /// @param tpToken_ The TP token address
    /// @return The pool reserve
    function getPoolReserve(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].reservePool;
    }

    /// @notice Get last fee accrued
    /// @param tpToken_ The TP token address
    /// @return The fee accrued
    function getFeeAccrued(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].getFeeAccrued();
    }

    // ============ Coverage Functions ============

    /// @notice Get the minimum coverage ratio required for a vault
    /// @param tpToken_ The TP token address
    /// @return minCoverage The minimum coverage ratio [PREC]
    function getMinCoverage(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].minCoverage;
    }

    /// @notice Get the liquidation coverage threshold
    /// @param tpToken_ The TP token address
    /// @return liquidationCoverage The liquidation coverage threshold [PREC]
    function getLiquidationCoverage(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].liquidationCoverage;
    }

    // ============ Interest Rate Functions ============

    /// @notice Get the current borrow fee percentage
    /// @param tpToken_ The TP token address
    /// @return borrowFee The borrow fee [PREC]
    function getBorrowFee(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].borrowFee;
    }

    /// @notice Get the next TP injection time
    /// @param tpToken_ The TP token address
    /// @return nextInjectionTime The timestamp of the next injection
    function getNextInjectionTime(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].nextInjectionTime;
    }

    /// @notice Get the TP injection time span
    /// @param tpToken_ The TP token address
    /// @return injectionTimeSpan The duration over which TP is injected
    function getInjectionTimeSpan(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].injectionTimeSpan;
    }

    /// @notice Get the current TP injection rate (TP per second)
    /// @param tpToken_ The TP token address
    /// @return injectionRate The TP injection rate [PREC]
    function getInjectionRate(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].injectionRate;
    }

    /// @notice Get the borrow interest rate from TP injection (per second)
    /// @param tpToken_ The TP token address
    /// @return borrowInjectionRate The borrow injection rate [PREC]
    function getBorrowInjectionRate(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].borrowInjectionRate;
    }

    /// @notice Get the TP inject rate for a given emission rate
    /// @dev This is used by the TPInjector to calculate injection rates per bucket
    /// @param tpToken_ The TP token address
    /// @param emissionRate_ The emission rate for the bucket [PREC]
    /// @return tpInjectRate The TP inject rate [PREC]
    function getTPInjectRate(address tpToken_, uint256 emissionRate_) external view returns (uint256) {
        return _pools[tpToken_].getTPInjectRate(emissionRate_);
    }

    // ============ Pool Parameter Functions ============

    /// @notice Get the utilization kink point
    /// @param tpToken_ The TP token address
    /// @return uKinkPoint The utilization kink point [PREC]
    function getUKinkPoint(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].uKinkPoint;
    }

    /// @notice Get the soft slope (below kink)
    /// @param tpToken_ The TP token address
    /// @return uSoftSlope The soft slope [PREC]
    function getUSoftSlope(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].uSoftSlope;
    }

    /// @notice Get the max slope (above kink)
    /// @param tpToken_ The TP token address
    /// @return uMaxSlope The max slope [PREC]
    function getUMaxSlope(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].uMaxSlope;
    }

    /// @notice Get the first brake kink
    /// @param tpToken_ The TP token address
    /// @return brakeFirstKink The first brake kink [PREC]
    function getBrakeFirstKink(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].brakeFirstKink;
    }

    /// @notice Get the second brake kink
    /// @param tpToken_ The TP token address
    /// @return brakeSecondKink The second brake kink [PREC]
    function getBrakeSecondKink(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].brakeSecondKink;
    }

    /// @notice Get the injection base factor
    /// @param tpToken_ The TP token address
    /// @return injectionBaseFactor The injection base factor [PREC]
    function getInjectionBaseFactor(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].injectionBaseFactor;
    }

    /// @notice Get the last update time
    /// @param tpToken_ The TP token address
    /// @return lastUpdateTime The last update timestamp
    function getLastUpdateTime(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].lastUpdateTime;
    }

    /// @notice Get the change in price of credit unit since last update
    /// @dev Returns deltaPCU which includes both utilization and injection interest
    /// @param tpToken_ The TP token address
    /// @return deltaPCU The change in PCU [PREC]
    function getDeltaPCU(address tpToken_) external view returns (uint256) {
        Pool.State storage pool = _pools[tpToken_];
        uint256 lastTimeInjectionApplicable = Math.min(block.timestamp, pool.nextInjectionTime);
        return pool.getDeltaPCU(pool.liquidity, pool.lastPCU, pool.lastUpdateTime, lastTimeInjectionApplicable);
    }

    // ============ Liquidation State Functions ============

    /// @notice Check if a vault is currently being liquidated
    /// @param user_ The user address
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return isLiquidating True if vault is in liquidation process
    function isVaultLiquidating(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (bool isLiquidating) {
        return _pools[tpToken_].isLiquidating[user_][mocBucket_];
    }

    /// @notice Check if a vault can start or continue a liquidation
    /// @dev Reverts while the protocol is paused or when the market price is invalid.
    /// Uses the current price and the fresh credit unit price.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return True if a liquidation can start or continue
    function isLiquidationAvailable(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view notPaused poolExists(tpToken_) returns (bool) {
        (uint256 pACtp, ) = _validateAndGetPACtp(mocBucket_, tpToken_);
        return _pools[tpToken_].isLiquidationAvailable(user_, mocBucket_, pACtp);
    }

    // ============ Queue Management Functions ============

    /// @notice Internal function to execute a queued operation (implements abstract function)
    /// @param operation_ The operation to execute
    /// @param operId_ The operation ID
    function _executeOper(QueuedOperation memory operation_, uint256 operId_) internal override {
        // solhint-disable-next-line no-empty-blocks
        try this.executeOper(operation_) {} catch (bytes memory returnData) {
            emit OperationError(operId_, returnData);
        }
    }

    /// @notice External function callable only by this contract to execute operation logic
    /// @param operation_ The operation to execute
    function executeOper(QueuedOperation calldata operation_) external {
        if (msg.sender != address(this)) revert OnlySelf();

        if (operation_.operType == OperType.BORROW) {
            // user's vault is used as collateral, recipient receives the TP tokens
            _executeBorrow(
                operation_.user,
                operation_.recipient,
                operation_.tpToken,
                operation_.mocBucket,
                operation_.amount
            );
        } else if (operation_.operType == OperType.REMOVE_AC_FROM_VAULT) {
            // user's vault is modified, recipient receives the AC tokens
            _executeRemoveACfromVault(
                operation_.user,
                operation_.recipient,
                operation_.tpToken,
                operation_.mocBucket,
                operation_.amount
            );
        } else if (operation_.operType == OperType.REPAY_WITH_AC) {
            // user repays their own debt using their own AC (no recipient differentiation)
            _executeRepayWithAC(operation_.user, operation_.tpToken, operation_.mocBucket, operation_.amount);
        }
    }

    /// @notice Allows the contract to receive coinbase for refunds when swapping
    receive() external payable {
        // Accept coinbase for refunds when swapping
    }

    /// @dev This empty reserved space is put in place to allow future versions to add new
    /// variables without shifting down storage in the inheritance chain.
    /// See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private _gap;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { MocUpgradable } from "@moc/moc-main/contracts/governance/MocUpgradable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import { IMocAdapter } from "./interfaces/IMocAdapter.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Coin } from "./lib/Coin.sol";

/**
 * @title MocLendingQueue
 * @author Money On Chain
 * @notice Base contract for managing a FIFO queue of operations with gas payment mechanism
 */
abstract contract MocLendingQueue is MocUpgradable, ReentrancyGuardUpgradeable {
    using Coin for IERC20;

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when queue configuration is invalid
    error InvalidQueueConfig();
    /// @notice Thrown when execution fee is insufficient
    /// @param required The required fee amount
    /// @param provided The provided fee amount
    error InsufficientExecutionFee(uint256 required, uint256 provided);
    /// @notice Thrown when execution fee exceeds maximum
    /// @param required The required fee amount
    /// @param provided The provided fee amount
    error ExcessiveExecutionFee(uint256 required, uint256 provided);

    // -----------------
    // Events
    // -----------------

    /// @notice Emitted when an operation is queued
    /// @param operId The operation ID
    /// @param operType The type of operation
    /// @param user The user who initiated the operation
    /// @param recipient The recipient of the operation
    /// @param tpToken The TP token address
    /// @param mocBucket The MoC bucket address
    /// @param amount The amount involved in the operation
    event OperationQueued(
        uint256 indexed operId,
        OperType operType,
        address indexed user,
        address recipient,
        address indexed tpToken,
        address mocBucket,
        uint256 amount
    );
    /// @notice Emitted when an operation execution fails
    /// @param operId The operation ID
    /// @param reason The error data
    event OperationError(uint256 operId, bytes reason);
    /// @notice Emitted when an operation is executed
    /// @param executor The address that executed the operation
    /// @param operId The operation ID
    event OperationExecuted(address indexed executor, uint256 indexed operId);

    /// @notice Operation types for queued operations
    enum OperType {
        NONE,
        BORROW,
        REMOVE_AC_FROM_VAULT,
        REPAY_WITH_AC
    }

    /// @notice Structure for queued operations
    struct QueuedOperation {
        OperType operType;
        address user; // The user who initiated the operation (payer)
        address recipient; // The user who will receive the benefits/effects of the operation
        address tpToken;
        address mocBucket;
        uint256 amount; // tpAmount for BORROW, acAmount for REMOVE_AC, creditUnits for REPAY_WITH_AC
        uint256 queuedBlk;
    }

    /// @notice Parameters for initializing the queue
    struct InitializeQueueParams {
        bool useQueue;
        uint256 minOperWaitingBlk;
        uint256 maxOperWaitingBlk;
        uint256 maxOperationPerBatch;
        uint256 borrowExecCost;
        uint256 removeACExecCost;
        uint256 repayWithACExecCost;
    }

    // -----------------
    // Storage
    // -----------------

    /// @notice Contract to adapt requirements for the different MoC protocols
    IMocAdapter public mocAdapter;
    /// @notice If true, operations that consume pACtp will be queued and executed later.
    bool public useQueue;
    /// @notice Amount of Operations created
    uint256 public operIdCount;
    /// @notice First operation to be executed
    uint256 public firstOperId;
    /// @notice Min amount of blocks the Operation should wait in the Queue before execution
    uint256 public minOperWaitingBlk;
    /// @notice Max amount of blocks the Operation should wait in the Queue. Even if there is no price update
    /// it can be executed after this amount of blocks
    uint256 public maxOperWaitingBlk;
    /// @notice Maximum number of operations that can be executed in a single batch
    uint256 public maxOperationPerBatch;
    /// @notice Total coinbase held for paying execution fees
    uint256 public coinbaseForPayExecutions;
    /// @notice Gas costs for each operation type
    mapping(OperType => uint256) public execCost;
    /// @notice Mapping from operation ID to queued operation
    mapping(uint256 operId => QueuedOperation) public operations;

    /// @notice Initialize queue parameters
    /// @param governor_ The governor contract address
    /// @param pauser_ The pauser contract address
    /// @param mocAdapter_ The MoC adapter contract address
    /// @param initializeQueueParams_ The parameters for initializing the queue
    function __MocLendingQueue_init(
        address governor_,
        address pauser_,
        address mocAdapter_,
        InitializeQueueParams calldata initializeQueueParams_
    ) internal onlyInitializing {
        __MocUpgradable_init(governor_, pauser_);
        __ReentrancyGuard_init();
        mocAdapter = IMocAdapter(mocAdapter_);
        useQueue = initializeQueueParams_.useQueue;
        minOperWaitingBlk = initializeQueueParams_.minOperWaitingBlk;
        maxOperWaitingBlk = initializeQueueParams_.maxOperWaitingBlk;
        maxOperationPerBatch = initializeQueueParams_.maxOperationPerBatch;
        operIdCount = 1;
        firstOperId = 1;

        // Set gas costs for each operation type
        execCost[OperType.BORROW] = initializeQueueParams_.borrowExecCost;
        execCost[OperType.REMOVE_AC_FROM_VAULT] = initializeQueueParams_.removeACExecCost;
        execCost[OperType.REPAY_WITH_AC] = initializeQueueParams_.repayWithACExecCost;
    }

    /// @notice Set the MoC Adapter contract
    /// @param mocAdapter_ The new MoC adapter contract address
    function setMocAdapter(address mocAdapter_) external onlyAuthorizedChanger {
        mocAdapter = IMocAdapter(mocAdapter_);
    }

    /// @notice Configure the queue system
    /// @param useQueue_ Whether to enable the queue system
    /// @param minOperWaitingBlk_ Minimum blocks to wait before operation execution
    /// @param maxOperWaitingBlk_ Maximum blocks to wait before operation expires
    /// @param maxOperationPerBatch_ Maximum number of operations that can be executed in a single batch
    function configureQueue(
        bool useQueue_,
        uint256 minOperWaitingBlk_,
        uint256 maxOperWaitingBlk_,
        uint256 maxOperationPerBatch_
    ) external onlyAuthorizedChanger {
        if (maxOperWaitingBlk_ <= minOperWaitingBlk_) revert InvalidQueueConfig();

        useQueue = useQueue_;
        minOperWaitingBlk = minOperWaitingBlk_;
        maxOperWaitingBlk = maxOperWaitingBlk_;
        maxOperationPerBatch = maxOperationPerBatch_;
    }

    /// @notice Set the gas cost for a specific operation type
    /// @param operType_ The operation type
    /// @param execCost_ The gas cost for this operation type
    function setExecutionCost(OperType operType_, uint256 execCost_) external onlyAuthorizedChanger {
        execCost[operType_] = execCost_;
    }

    // ============ Queue Operation Functions ============

    /// @notice Queue an operation for later execution
    /// @param operType_ The type of operation
    /// @param recipient_ The address that will receive the benefits/effects of the operation
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param amount_ The amount parameter (meaning depends on operation type)
    /// @return operId The operation ID
    function _queueOperation(
        OperType operType_,
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 amount_
    ) internal returns (uint256 operId) {
        // Calculate required gas payment
        uint256 gas = execCost[operType_];
        uint256 requiredPayment = gas * _getBaseFee();

        // Check if user sent enough coinbase to cover gas
        if (msg.value < requiredPayment) {
            revert InsufficientExecutionFee(requiredPayment, msg.value);
        }

        // If the value sent is 10x higher than network required, we assumed user error
        if (msg.value > requiredPayment * 10) {
            revert ExcessiveExecutionFee(requiredPayment, msg.value);
        }

        operId = operIdCount;

        operations[operId] = QueuedOperation({
            operType: operType_,
            user: msg.sender,
            recipient: recipient_,
            tpToken: tpToken_,
            mocBucket: mocBucket_,
            amount: amount_,
            queuedBlk: block.number
        });

        ++operIdCount;
        coinbaseForPayExecutions += msg.value;

        emit OperationQueued(operId, operType_, msg.sender, recipient_, tpToken_, mocBucket_, amount_);
        return operId;
    }

    /// @notice Execute multiple operations in FIFO order
    /// @param recipient_ Address to receive the gas payment
    function execute(address payable recipient_) external notPaused nonReentrant {
        uint256 currentOperId = firstOperId;
        uint256 lastOperId;
        uint256 limitBlk;
        uint256 totalExecutionFee;
        uint256 blocksSinceLastPublication = block.number - mocAdapter.getLastPublicationBlock();
        lastOperId = Math.min(operIdCount, currentOperId + maxOperationPerBatch);
        limitBlk = _getLastBlockToExecute(blocksSinceLastPublication, minOperWaitingBlk, maxOperWaitingBlk);

        // loop through all pending Operations
        while (currentOperId < lastOperId) {
            QueuedOperation memory operation = operations[currentOperId];
            // If current Operation has not met the waiting block criteria, we end the loop
            if (operation.queuedBlk > limitBlk) break;

            _executeOper(operation, currentOperId);
            emit OperationExecuted(msg.sender, currentOperId);
            delete operations[currentOperId];

            ++currentOperId;
            totalExecutionFee += execCost[operation.operType];
        }

        // Calculate total fee in wei (coinbase)
        totalExecutionFee = totalExecutionFee * _getBaseFee();
        // Limit payment to available balance (safety check)
        totalExecutionFee = Math.min(coinbaseForPayExecutions, totalExecutionFee);

        // Define new reference to queue beginning
        firstOperId = currentOperId;
        coinbaseForPayExecutions -= totalExecutionFee;
        // Send total gas payment to recipient
        Coin.COINBASE.coinTransfer(recipient_, totalExecutionFee);
    }

    /// @notice Internal function to execute a queued operation
    /// @param operation_ The operation to execute
    /// @param operId_ The operation ID
    function _executeOper(QueuedOperation memory operation_, uint256 operId_) internal virtual;

    /// @notice gets the last block in which the queued operations can be executed.
    /// Only operations enqueued before `blocksSinceLastPublication_` can be executed,
    /// but they must have been queued for at least `minOperWaitingBlk_` and at most `maxOperWaitingBlk_`
    /// @param blocksSinceLastPublication_ amount of blocks since last price publication
    /// @param minOperWaitingBlk_ min amount of blocks the operation should wait in the Queue before execution
    /// @param maxOperWaitingBlk_ max amount of blocks the operation should wait in the Queue before execution
    /// @return lastBlockToExecute last block to execute operations
    function _getLastBlockToExecute(
        uint256 blocksSinceLastPublication_,
        uint256 minOperWaitingBlk_,
        uint256 maxOperWaitingBlk_
    ) internal view returns (uint256 lastBlockToExecute) {
        uint256 qBlocksBefore;
        if (blocksSinceLastPublication_ >= maxOperWaitingBlk_) {
            qBlocksBefore = maxOperWaitingBlk_;
        } else {
            // when maxOperWaitingBlk_ < blocksSinceLastPublication_, this max is not necessary to calculate
            // because maxOperWaitingBlk_ is always > minOperWaitingBlk_ by parameter
            qBlocksBefore = Math.max(minOperWaitingBlk_, blocksSinceLastPublication_);
        }
        return block.number - qBlocksBefore;
    }

    /// @notice Internal function to get the current base fee
    /// @return The current block base fee
    function _getBaseFee() internal view virtual returns (uint256) {
        return block.basefee;
    }

    // ============ View Functions ============

    /// @notice Get the execution fee for a given operation type
    /// @param operType_ The operation type
    /// @return currentExecFee The current execution fee in coinbase
    function getExecFee(OperType operType_) public view returns (uint256 currentExecFee) {
        unchecked {
            currentExecFee = execCost[operType_] * _getBaseFee();
        }
    }

    /// @notice Get the number of pending operations
    /// @return count The number of pending operations
    function getPendingOperationsCount() external view returns (uint256 count) {
        return operIdCount - firstOperId;
    }

    /// @notice true if the queue is empty
    /// @return True if the queue is empty
    function isEmpty() public view returns (bool) {
        return firstOperId == operIdCount;
    }

    /// @notice true if the queue has at least one Operation ready to be executed
    /// @param blocksSinceLastPublication_ amount of blocks since last price publication
    /// @return True if there are operations ready to execute
    function readyToExecute(uint256 blocksSinceLastPublication_) external view returns (bool) {
        if (isEmpty()) return false;
        QueuedOperation memory operInfo = operations[firstOperId];
        return (operInfo.queuedBlk <=
            _getLastBlockToExecute(blocksSinceLastPublication_, minOperWaitingBlk, maxOperWaitingBlk));
    }

    /// @dev This empty reserved space is put in place to allow future versions to add new
    /// variables without shifting down storage in the inheritance chain.
    /// See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private __gap;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { MocLendingManager } from "./MocLendingManager.sol";
import { MocLendingPool as Pool } from "./lib/MocLendingPool.sol";
import { IMocAdapter } from "./interfaces/IMocAdapter.sol";
import { C } from "./lib/Constants.sol";
import { FixedPoint } from "./lib/FixedPoint.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title MocLendingReader
/// @author Money On Chain
/// @notice Helper contract to read computed data from MocLendingManager
/// @dev This contract contains view functions that perform calculations to reduce the size of MocLendingManager
contract MocLendingReader {
    using Pool for Pool.State;
    using FixedPoint for uint256;

    /// @notice Reference to the MocLendingManager contract
    MocLendingManager public immutable LENDING_MANAGER;

    /// @notice Thrown when the AC / TP price is invalid
    error InvalidPrice();

    /// @notice Constructor
    /// @param lendingManager_ The address of the MocLendingManager contract
    constructor(address payable lendingManager_) {
        LENDING_MANAGER = MocLendingManager(lendingManager_);
    }

    /// @notice Internal function to get and validate AC/TP price
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @return pACtp The validated AC/TP price [PREC]
    function _validateAndGetPACtp(address mocBucket_, address tpToken_) internal view returns (uint256 pACtp) {
        // reverts if mocBucket or price are invalid
        (pACtp, ) = LENDING_MANAGER.mocAdapter().validateAndGetPACtp(mocBucket_, tpToken_);
    }

    /// @notice Calculate the coverage ratio of a vault
    /// @dev Coverage = (AC balance * AC/TP price) / (credit units * PCU)
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return coverage The coverage ratio [PREC]. Returns MAX_UINT if no debt
    function getCoverage(address user_, address tpToken_, address mocBucket_) external view returns (uint256 coverage) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return getCoverageWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Calculate the coverage ratio of a vault with a specific AC/TP price
    /// @dev Coverage = (AC balance * AC/TP price) / (credit units * PCU)
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return coverage The coverage ratio [PREC]. Returns MAX_UINT if no debt
    function getCoverageWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (uint256 coverage) {
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);
        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultCollateralBalance(user_, tpToken_, mocBucket_);
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        return Pool.vaultCoverage(vaultCreditBalance, vaultACBalance, pCU, pACtp_);
    }

    /// @notice Check if a vault is liquidable
    /// @dev Delegates to the Manager's canonical liquidation eligibility check.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return isLiquidable True if the vault can be liquidated
    function isVaultLiquidable(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (bool isLiquidable) {
        return LENDING_MANAGER.isLiquidationAvailable(user_, tpToken_, mocBucket_);
    }

    /// @notice Check if a vault is liquidable with a specific AC/TP price
    /// @dev This is a preview with a caller-provided price, not the canonical eligibility check.
    /// A vault is liquidable when coverage <= liquidationCoverage.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return isLiquidable True if the vault can be liquidated at this price
    function isVaultLiquidableWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (bool isLiquidable) {
        if (LENDING_MANAGER.isVaultLiquidating(user_, tpToken_, mocBucket_)) {
            return LENDING_MANAGER.getUserVaultCollateralBalance(user_, tpToken_, mocBucket_) > 0;
        }

        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);

        // If no debt, cannot be liquidated
        if (vaultCreditBalance == 0) return false;

        uint256 liquidationCoverage = LENDING_MANAGER.getLiquidationCoverage(tpToken_);
        uint256 coverage = getCoverageWithPACtp(user_, tpToken_, mocBucket_, pACtp_);

        return coverage <= liquidationCoverage;
    }

    /// @notice Calculate the AC/TP price at which a vault would become liquidable
    /// @dev Returns the pACtp where coverage equals liquidationCoverage
    /// If vault has no debt, returns 0 (cannot be liquidated)
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return pACtpLiquidation The AC/TP price [PREC] at which the vault becomes liquidable. Returns 0 if no debt.
    function getLiquidationPrice(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256 pACtpLiquidation) {
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);

        // If no debt, cannot be liquidated
        if (vaultCreditBalance == 0) return 0;

        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultCollateralBalance(user_, tpToken_, mocBucket_);

        // If no AC collateral, already liquidable at any price
        if (vaultACBalance == 0) return C.MAX_UINT;

        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);
        uint256 liquidationCoverage = LENDING_MANAGER.getLiquidationCoverage(tpToken_);

        // At liquidation: coverage = (vaultACBalance * pACtp) / (vaultCreditBalance * pCU) = liquidationCoverage
        // Solving for pACtp: pACtp = (liquidationCoverage * vaultCreditBalance * pCU) / vaultACBalance
        // [PREC] = [PREC] * [N] * [PREC] / [N] * [PREC]
        pACtpLiquidation = (liquidationCoverage * vaultCreditBalance * pCU) / (vaultACBalance * C.PRECISION);

        return pACtpLiquidation;
    }

    /// @notice Calculate the maximum TP tokens a user can borrow from their vault
    /// @dev Considers: AC collateral in vault, existing credit units, pool liquidity,
    /// and minCoverage requirement. Gets price from adapter.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @return maxTPToBorrow The maximum TP tokens that can be borrowed
    function getMaxTPToBorrow(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256 maxTPToBorrow) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return getMaxTPToBorrowWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Calculate the maximum TP tokens a user can borrow from their vault with a specific AC/TP price
    /// @dev Considers: AC collateral in vault, existing credit units, pool liquidity, and minCoverage requirement
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return maxTPToBorrow The maximum TP tokens that can be borrowed
    function getMaxTPToBorrowWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (uint256 maxTPToBorrow) {
        // Get vault state
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);
        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultCollateralBalance(user_, tpToken_, mocBucket_);

        // A debt-free vault has not snapshotted its payment yet. Preview the
        // configured amount so the quoted borrowing capacity matches borrow().
        if (vaultCreditBalance == 0) {
            uint256 liquidationPayment = LENDING_MANAGER.liquidationPaymentAC(mocBucket_, tpToken_);
            if (vaultACBalance <= liquidationPayment) return 0;
            vaultACBalance -= liquidationPayment;
        }

        // If no AC in vault, cannot borrow
        if (vaultACBalance == 0) return 0;

        // Get current price of credit unit
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        // Get minimum coverage required
        uint256 minCoverage = LENDING_MANAGER.getMinCoverage(tpToken_);

        // Calculate max TP based on collateral constraint:
        // coverage = (vaultACBalance * pACtp) / (totalCreditUnits * pCU) >= minCoverage
        // Solving for totalCreditUnits:
        // totalCreditUnits <= (vaultACBalance * pACtp) / (minCoverage * pCU)
        // [N] = [N] * [PREC] * [PREC] / [PREC] * [PREC]
        uint256 maxTotalCreditUnits = (vaultACBalance * pACtp_).divPrec((minCoverage * pCU));

        // Subtract existing credit units to get additional credit units available
        uint256 additionalCreditUnits = maxTotalCreditUnits > vaultCreditBalance
            ? maxTotalCreditUnits - vaultCreditBalance
            : 0;

        // Convert credit units to TP tokens
        // [N] = [N] * [PREC] / [PREC]
        uint256 maxTPFromCollateral = additionalCreditUnits.mulPrec(pCU);

        // Get available liquidity in pool
        uint256 poolLiquidity = LENDING_MANAGER.getPoolLiquidity(tpToken_);

        // Return the minimum of collateral-based limit and pool liquidity
        return Math.min(maxTPFromCollateral, poolLiquidity);
    }

    /// @notice Calculate the maximum AC tokens a user can remove from their vault
    /// @dev Considers: existing AC collateral, credit units debt, and minCoverage requirement. Gets price from adapter.
    /// If there's no debt, all AC can be removed. If there's debt, must maintain minCoverage.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @return maxACToRemove The maximum AC tokens that can be removed
    function getMaxACToRemove(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256 maxACToRemove) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return getMaxACToRemoveWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Calculate the maximum AC tokens a user can remove from their vault with a specific AC/TP price
    /// @dev Considers: existing AC collateral, credit units debt, and minCoverage requirement
    /// If there's no debt, all AC can be removed. If there's debt, must maintain minCoverage.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return maxACToRemove The maximum AC tokens that can be removed
    function getMaxACToRemoveWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (uint256 maxACToRemove) {
        // Get vault state
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);
        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultCollateralBalance(user_, tpToken_, mocBucket_);

        // If no AC in vault, cannot remove anything
        if (vaultACBalance == 0) return 0;

        // If no debt, can remove all AC
        if (vaultCreditBalance == 0) return vaultACBalance;

        // Get current price of credit unit
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        // Get minimum coverage required
        uint256 minCoverage = LENDING_MANAGER.getMinCoverage(tpToken_);

        // Calculate min AC required to maintain minCoverage:
        // coverage = (minACBalance * pACtp) / (vaultCreditBalance * pCU) >= minCoverage
        // Solving for minACBalance:
        // minACBalance >= (vaultCreditBalance * pCU * minCoverage) / pACtp
        // [N] = [N] * [PREC] * [PREC] / [PREC] * [PREC]
        uint256 minACRequired = (vaultCreditBalance * pCU * minCoverage) / (pACtp_ * C.PRECISION);

        // Max to remove is current balance minus minimum required
        if (vaultACBalance <= minACRequired) return 0;

        return vaultACBalance - minACRequired;
    }

    /// @notice Calculate the brake factor for TP injection based on emission rate
    /// @dev The brake factor reduces injection rate when emission is high:
    /// - Returns 1.0 when emission <= brakeFirstKink (no brake)
    /// - Returns linear interpolation between brakeFirstKink and brakeSecondKink
    /// - Returns 0 when emission >= brakeSecondKink (full brake)
    /// @param tpToken_ The TP token address
    /// @param emissionRate_ The current emission rate [PREC]
    /// @return brakeFactor The brake factor [PREC] (0 to C.ONE)
    function getBrakeFactor(address tpToken_, uint256 emissionRate_) external view returns (uint256 brakeFactor) {
        uint256 brakeFirstKink = LENDING_MANAGER.getBrakeFirstKink(tpToken_);
        uint256 brakeSecondKink = LENDING_MANAGER.getBrakeSecondKink(tpToken_);

        return Pool.calculateBrakeFactor(emissionRate_, brakeFirstKink, brakeSecondKink);
    }

    /// @notice Calculate the utilization rate of a pool
    /// @dev Utilization is defined as: total borrows / (total borrows + total liquidity)
    /// @param tpToken_ The TP token address
    /// @return utilization The utilization rate [PREC]
    function getUtilizationRate(address tpToken_) external view returns (uint256 utilization) {
        uint256 creditSupply = LENDING_MANAGER.getPoolCreditSupply(tpToken_);
        uint256 liquidity = LENDING_MANAGER.getPoolLiquidity(tpToken_);
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        return Pool.calculateUtilizationRate(creditSupply, liquidity, pCU);
    }

    /// @notice Returns the list of unique (acToken, tpToken) pairs for all pending operations in the queue.
    /// @dev Each element is 40 bytes: abi.encode(acToken, tpToken)
    /// This function helps off-chain services know which price pairs they need to publish.
    /// @return pairs An array of encoded address pairs (acToken, tpToken).
    function getPACtpNeeded() external view returns (bytes[] memory pairs) {
        IMocAdapter mocAdapter = LENDING_MANAGER.mocAdapter();
        // Get queue state from lending manager
        uint256 operIdCount = LENDING_MANAGER.operIdCount();
        uint256 firstOperId = LENDING_MANAGER.firstOperId();
        uint256 pendingCount = operIdCount - firstOperId;

        if (pendingCount == 0) return new bytes[](0);

        bytes[] memory tempPairs = new bytes[](pendingCount);
        bytes32[] memory seenHashes = new bytes32[](pendingCount);
        uint256 uniqueCount;

        for (uint256 i = 0; i < pendingCount; ++i) {
            // Read operation from lending manager
            (
                , // operType - not needed
                , // user - not needed
                , // recipient - not needed
                address tpToken,
                address mocBucket,
                , // amount - not needed

            ) = LENDING_MANAGER.operations(firstOperId + i); // queuedBlk - not needed
            (address acToken, ) = mocAdapter.validateAndGetACToken(mocBucket);
            bytes memory packed = abi.encode(acToken, tpToken);
            bytes32 hash = keccak256(packed);

            bool duplicate = false;
            for (uint256 j = 0; j < uniqueCount; ++j) {
                if (seenHashes[j] == hash) {
                    duplicate = true;
                    break;
                }
            }

            if (!duplicate) {
                seenHashes[uniqueCount] = hash;
                tempPairs[uniqueCount] = packed;
                ++uniqueCount;
            }
        }

        pairs = new bytes[](uniqueCount);
        for (uint256 i = 0; i < uniqueCount; ++i) {
            pairs[i] = tempPairs[i];
        }

        return pairs;
    }
}

